// build-settings.mjs — generated files for the settings page (app/settings/).
//
//   npm run build:settings
//
// Writes:
//   app/settings/profile-validate.js  ajv standalone validators for schema/profile.schema.json
//                                     (exports validateSaved, validateGenerate; default = generate),
//                                     as a browser ES module with no imports (ajv's two runtime
//                                     helpers are inlined below), so the page needs no CDN.
//   app/settings/notice.js            the notice text from NOTICE-TO-USERS.md, so the page shows
//                                     exactly the words in that file and never drifts from it.
//   app/settings/relay-source.js      the relay's code (worker/src/*.js) for the privacy section.
//
// Both outputs are checked in so the static page works without a build step; rerun this script
// whenever the schema or the notice changes.

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createRequire } from 'node:module';
import Ajv2020Mod from 'ajv/dist/2020.js';
import standaloneMod from 'ajv/dist/standalone/index.js';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const OUT_DIR = path.join(ROOT, 'app', 'settings');
const require = createRequire(import.meta.url);
const Ajv2020 = Ajv2020Mod.default || Ajv2020Mod;
const standaloneCode = standaloneMod.default || standaloneMod;

// ---- 1. validator ------------------------------------------------------------------------
const schema = JSON.parse(fs.readFileSync(path.join(ROOT, 'schema', 'profile.schema.json'), 'utf8'));
// Two validators from one schema:
//   validateSaved     the schema as written: a saved profile.json (never holds the access key)
//   validateGenerate  the same plus `access` with `access_key` required: what generateBinder() gets
const strict = structuredClone(schema);
strict.$id = 'goettschepreppy/profile-generate.schema.json';
strict.required = [...new Set([...strict.required, 'access'])];
strict.properties.access.required = [...new Set(['access_key', ...strict.properties.access.required])];
const ajv = new Ajv2020({ code: { source: true, esm: true }, allErrors: true, strict: false,
  schemas: [schema, strict] });
let code = standaloneCode(ajv, { validateSaved: schema.$id, validateGenerate: strict.$id, default: strict.$id });

// ajv's standalone output still `require`s small runtime helpers. Inline them as CommonJS
// shims so the file is a plain browser module. Only the modules listed here may appear.
const INLINE = {
  'ajv/dist/runtime/ucs2length': require.resolve('ajv/dist/runtime/ucs2length'),
  'ajv/dist/runtime/equal': require.resolve('ajv/dist/runtime/equal'),
  'fast-deep-equal': require.resolve('fast-deep-equal'),
};
const used = new Set();
code = code.replace(/require\("([^"]+)"\)/g, (m, name) => {
  if (!INLINE[name]) throw new Error(`build-settings: unexpected runtime require ${name}`);
  used.add(name);
  return `__req(${JSON.stringify(name)})`;
});
// equal.js itself requires fast-deep-equal
if (used.has('ajv/dist/runtime/equal')) used.add('fast-deep-equal');
const shims = [...used].map(name => {
  const src = fs.readFileSync(INLINE[name], 'utf8').replace(/\/\/# sourceMappingURL=.*$/m, '');
  return `${JSON.stringify(name)}: function (module, exports, require) {\n${src}\n}`;
}).join(',\n');
const header = `// GENERATED by scripts/build-settings.mjs from schema/profile.schema.json. Do not edit.
// ajv ${require('ajv/package.json').version} standalone validator (MIT, Evgeny Poberezkin) with its runtime
// helpers inlined (fast-deep-equal, MIT, Evgeny Poberezkin).
const __mods = {
${shims}
};
const __cache = {};
function __req(name) {
  if (__cache[name]) return __cache[name].exports;
  const module = { exports: {} };
  __cache[name] = module;
  __mods[name](module, module.exports, __req);
  return module.exports;
}
`;
// any require left in the validator body would fail in the browser
if (/\brequire\(/.test(code)) throw new Error('build-settings: a require() survived inlining');
code = header + code.replace(/^"use strict";/, '');
fs.writeFileSync(path.join(OUT_DIR, 'profile-validate.js'), code);

// ---- 2. notice ---------------------------------------------------------------------------
const md = fs.readFileSync(path.join(ROOT, 'NOTICE-TO-USERS.md'), 'utf8');
const body = md.split(/^---\s*$/m).slice(1).join('---');
const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const inline = s => esc(s).replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
const sections = {};
for (const chunk of body.split(/^## /m).slice(1)) {
  const [titleLine, ...rest] = chunk.split('\n');
  const paragraphs = rest.join('\n').split(/\n\s*\n/).map(p => p.replace(/\s*\n\s*/g, ' ').trim()).filter(Boolean);
  sections[titleLine.trim()] = { title: titleLine.trim(), paragraphs: paragraphs.map(inline) };
}
const pick = prefix => {
  const k = Object.keys(sections).find(t => t.startsWith(prefix));
  if (!k) throw new Error(`build-settings: notice section "${prefix}" not found in NOTICE-TO-USERS.md`);
  return sections[k];
};
const notice = {
  neverStored: pick('Your answers are never stored'),
  privateCopy: pick('This file is your private copy'),
  whatItIs: pick('What this binder is'),
};
fs.writeFileSync(path.join(OUT_DIR, 'notice.js'),
  `// GENERATED by scripts/build-settings.mjs from NOTICE-TO-USERS.md. Do not edit.\n` +
  `export const NOTICE = ${JSON.stringify(notice, null, 2)};\n`);

// ---- 3. relay source, shown in the page's privacy section (decision G13) -------------------
// The relay's own code (worker/src/*.js), so a friend can read what it does with their answers.
const relayDir = path.join(ROOT, 'worker', 'src');
const relayFiles = fs.existsSync(relayDir)
  ? fs.readdirSync(relayDir).filter(f => f.endsWith('.js')).sort().map(f => ({ name: `worker/src/${f}`, text: fs.readFileSync(path.join(relayDir, f), 'utf8') }))
  : [];
fs.writeFileSync(path.join(OUT_DIR, 'relay-source.js'),
  `// GENERATED by scripts/build-settings.mjs from worker/src/*.js. Do not edit.\n` +
  `export const RELAY_SOURCE = ${JSON.stringify(relayFiles)};\n`);

console.log(`build-settings: wrote app/settings/profile-validate.js (${(code.length / 1024).toFixed(0)} KB) app/settings/notice.js and app/settings/relay-source.js (${relayFiles.length} files)`);
